function plannerKey(){return 'playbook-planner-v1-'+current.id;}
function plannerStageColour(index){
 const c=structureColour(index);
 return `--stage-ink:${c.ink};--stage-accent:${c.marker};--stage-header:${c.paper};--stage-paper:${c.paper};--stage-example:#fff;`;
}
function plannerFields(s,i){
 const textOnly=current.id==='test-prove' && i===0;
 return [
 ['line',textOnly?'My on-screen text':'My spoken line',textOnly?'Text example to adapt':'Spoken example to adapt',s[3],'Write your version here. Include the answer here if this stage delivers the payoff.'],
 ['visual','What I’ll film','Filming reference',s[6],'Describe your action, framing or evidence.'],
 ['question','What my viewer might think','Likely viewer thoughts in the original video',referenceThoughts(current,i),'Adapt the original viewer question to your product. This is a thought in their head—not something you say.'],
 ['loop','Loop tracking note · optional','What this stage opens or answers',s[5],'Planning only—not another spoken line. Note the question opened, held or answered.']
 ];
}
function renderPlanner(){
 try{plannerDraft=JSON.parse(localStorage.getItem(plannerKey())||'{}')||{};}catch{plannerDraft={};}
 if(typeof plannerDraft!=='object'||Array.isArray(plannerDraft))plannerDraft={};
 $('planner-status').textContent='';$('planner-format').textContent=current.format;
 $('planner-product').value=plannerDraft.product||'';$('planner-angle').value=plannerDraft.angle||'';
 $('planner-stages').innerHTML=`<div class="planner-stage"><div class="stage-body"><strong>Separate on-screen text hook</strong><p class="caption">Text example to adapt: ${esc(plannerTextHooks[current.id])}</p><label for="planner-text-hook">My on-screen text</label><textarea id="planner-text-hook" placeholder="Write your text hook…">${esc(String(plannerDraft.textHook||''))}</textarea></div></div>`+(planners[current.id]||[]).map((s,i)=>`<details class="planner-stage stage-coloured" style="${plannerStageColour(stageGroups[current.id][i])}" ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span> ${esc(s[0])}<small>Reference: ${esc(s[1])}</small></summary><div class="stage-body"><p>${esc(s[2])}</p>${plannerFields(s,i).map(([key,label,exampleLabel,example,hint])=>`<div class="planner-field"><label for="stage-${i}-${key}">${label}</label><p class="planner-example" id="stage-${i}-${key}-example"><strong>${exampleLabel}:</strong> ${esc(example)}</p><textarea id="stage-${i}-${key}" data-stage="${i}" data-field="${key}" aria-describedby="stage-${i}-${key}-example stage-${i}-${key}-help" placeholder="Write your version…">${esc(String(plannerDraft[i]?.[key]||''))}</textarea><p class="caption" id="stage-${i}-${key}-help">${esc(hint)}</p></div>`).join('')}</div></details>`).join('');
 $('planner-text-hook').oninput=()=>{plannerDraft.textHook=$('planner-text-hook').value;savePlanner();};
 document.querySelectorAll('#planner-stages textarea[data-stage]').forEach(el=>el.oninput=()=>{const i=el.dataset.stage;plannerDraft[i]=plannerDraft[i]||{};plannerDraft[i][el.dataset.field]=el.value;savePlanner();});
}
function savePlanner(){plannerDraft.product=$('planner-product').value;plannerDraft.angle=$('planner-angle').value;try{localStorage.setItem(plannerKey(),JSON.stringify(plannerDraft));$('planner-status').textContent='Draft saved on this device';}catch{$('planner-status').textContent='Unable to save here—copy your draft to Notion';}}
function plannerMarkdown(blank=false){
 const d=blank?{}:plannerDraft;
 const out=['# '+current.title+' — Script Planner','', '**Format:** '+current.format,'**Product:** '+(d.product||'[Your product]'),'**Audience / angle:** '+(d.angle||'[Who this is for and the problem or desire]'),'', '**Text example to adapt:** '+plannerTextHooks[current.id],'**My on-screen text:** '+(d.textHook||'[Write your text hook]'),'', 'Write the script once. Viewer thoughts and loop tracking are planning notes, not extra dialogue. A payoff belongs in the spoken line or filming action of the stage that delivers it.','Reference timings show the original video, not a required length for your script.',''];
 (planners[current.id]||[]).forEach((s,i)=>{const v=d[i]||{};out.push('## '+(i+1)+'. '+s[0],'','Reference: '+s[1],s[2],'');plannerFields(s,i).forEach(([key,label,exampleLabel,example,hint])=>{out.push('**'+exampleLabel+':** '+example,'**'+label+':** '+(v[key]||'[Write your version]'),hint,'');});});
 out.push('## Before filming','','- [ ] The opening promise gets a clear payoff in my spoken line or demonstration.','- [ ] Viewer thoughts and loop notes are not extra dialogue.','- [ ] My demonstration matches what I say.','- [ ] Claims, personal experience and any deal are accurate.','- [ ] The CTA tells the viewer what to do next.');return out.join('\n');
}
async function copyPlanner(blank=false){const text=plannerMarkdown(blank);try{if(!navigator.clipboard?.writeText)throw Error('clipboard unavailable');await navigator.clipboard.writeText(text);$('planner-status').textContent=blank?'Blank template copied—paste into Notion':'Planner copied—paste into Notion';$('copy-fallback').hidden=true;}catch{$('copy-fallback').hidden=false;$('planner-copy-text').value=text;$('planner-copy-text').focus();$('planner-copy-text').select();$('planner-status').textContent='Select and copy the text below, then paste into Notion';}}

